// 对页面内容做 djb2 哈希，和上次哈希比对（哈希存在工作流静态数据里）
const page = $input.first();
const body = typeof page.json.data === 'string' ? page.json.data : JSON.stringify(page.json);
let h = 5381;
for (let i = 0; i < body.length; i++) h = ((h << 5) + h + body.charCodeAt(i)) >>> 0;
const hash = h.toString(16);
const store = $getWorkflowStaticData('global');
const prev = store.lastHash || '';
store.lastHash = hash;
return [{ json: {
  url: page.json.url || '目标页面',
  hash,
  previousHash: prev || '首次运行(尚无历史)',
  changed: prev ? hash !== prev : '激活工作流后开始记录',
  checkedAt: new Date().toISOString()
} }];
